#!/usr/bin/env bash
set -euo pipefail
root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.."&&pwd)";cd "$root";lr="${HOME}/.local/iverilog/usr";iv="${lr}/bin/iverilog";vp="${lr}/bin/vvp";base="$(find "${lr}/lib" -type d -name ivl -print -quit)"
src=(rtl/bf16_to_fp32.sv rtl/fp32_to_bf16_rne.sv rtl/fp32_add.sv rtl/fp32_mul.sv rtl/fp32_add_pipe4.sv rtl/fp32_mul_pipe4.sv rtl/bf16_rsqrt_lut256.sv rtl/mixed_precision_bank_reducer_pingpong.sv rtl/mixed_precision_global_reducer16_pipe.sv rtl/mixed_precision_scalar_nr2_pipe.sv rtl/mixed_precision_scalar_engine_array.sv rtl/mixed_precision_bank_apply_pipe.sv rtl/mixed_precision_row_context_table.sv rtl/mixed_precision_multirow_datapath.sv verification/groot_normalization/mixed_precision_multirow_tb.sv)
for lanes in 4 8 16;do out="${TMPDIR:-/tmp}/mixed_precision_multirow_${lanes}.out";"$iv" -B "$base" -g2012 -Wall -s mixed_precision_multirow_tb -P mixed_precision_multirow_tb.LANES="$lanes" -P mixed_precision_multirow_tb.SCALAR_ENGINES=4 -o "$out" "${src[@]}";"$vp" -M "$base" "$out";done
